import { defineExternalSignals } from "../core/composition/define-external-signals.js";
import { defineFeature } from "../core/composition/define-feature.js";
import { resolveVttSegment } from "../media/dom/text/resolve-vtt-segment.js";
import { loadTextTrackSegments } from "../behaviors/dom/load-segments.js";
import { setupTextTrackActors } from "../behaviors/dom/setup-text-track-actors.js";
import { switchTextTrack } from "../behaviors/track-switching.js";
import { resolveTextTrack } from "../behaviors/resolve-track.js";
import { addSubtitlesTracksToMedia, getShowingSubtitlesTrackFromMedia, removeAllSubtitlesTracksFromMedia } from "../media/dom/text/text-track-slots.js";
import { syncTextTracks } from "../behaviors/dom/sync-text-tracks.js";
//#region src/playback/features/text-tracks.ts
/** The behaviors the feature composes, in setup order. */
const behaviors = [
	resolveTextTrack,
	switchTextTrack,
	syncTextTracks,
	setupTextTrackActors,
	loadTextTrackSegments,
	defineExternalSignals()({ state: ["userTextTrackSelection"] })
];
/** The config defaults the feature contributes. */
const defaultConfig = {
	enableDefaultTrack: true,
	resolveTextTrackSegment: resolveVttSegment,
	addSubtitlesTracksToMedia,
	getShowingSubtitlesTrackFromMedia,
	removeAllSubtitlesTracksFromMedia
};
/** The state values the feature seeds. */
const initialState = {};
/**
* Adds the source's subtitle and caption renditions to the media element as text tracks and loads the WebVTT cues of
* the showing one. Honors the user's `userTextTrackSelection`, including `'off'`.
*
* Requires, from other features:
*
* - A writer of `state.currentTime`, such as `currentTimeFeature`; without one, cue loading stops after the first window.
* - A writer of `state.loadActivated`, such as `initialLoadFeature`, or a seeded `loadActivated: true`.
*
* Content whose timestamps don't start at zero also needs `shiftTextTimestampsFeature`, or its cues are misaligned.
*/
const textTracksFeature = defineFeature({
	behaviors,
	defaultConfig,
	initialState
});
//#endregion
export { behaviors, defaultConfig, initialState, textTracksFeature };
